{
  "definition_simple": "没有限量，无法计算，多形容前途、功德或潜力极大。",
  "definition_standard": "无法计量；没有限度。多用作定语或谓语，常用于“前途无量”、“功德无量”等固定搭配中，表示极其广大、不可限量。",
  "pos": "形容词",
  "semantic_class": "property",
  "sentences": [
    {
      "text": "小明学习非常刻苦，老师夸他前途无量。",
      "tier": "T1"
    },
    {
      "text": "年轻人勇于拼搏，未来的发展潜力无量。",
      "tier": "T2"
    },
    {
      "text": "修建这所希望小学是一件功德无量的大善事。",
      "tier": "T2"
    },
    {
      "text": "这项新能源技术一旦研发成功，市场价值不可估量、商机无量。",
      "tier": "T3"
    },
    {
      "text": "佛家常说慈悲心能广积善缘，所得福报亦是无量无边。",
      "tier": "T3"
    },
    {
      "text": "宇宙浩瀚，繁星如海，其中蕴含着无量的奥秘等待人类去探寻。",
      "tier": "T4"
    },
    {
      "text": "科研团队历经数载攻克技术壁垒，此项突破对国家工业升级贡献无量。",
      "tier": "T4"
    },
    {
      "text": "先生毕生致力于古籍整理与抢救，虽甘于寂寞，然其学术泽被后世，实属功德无量。",
      "tier": "T5"
    },
    {
      "text": "大乘经典有云：应发无量心，誓度无量众生，以无边愿力铸就解脱之途。",
      "tier": "T5"
    },
    {
      "text": "观夫天地化生，气机流转，其生生不息之生机与造化伟力，诚浩瀚而无量也。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "无良",
      "explanation": "拼音同为 wúliáng，声调完全相同，但“无良”意为没有良心、不道德，常用于“无良商家”，与褒义/中性的“无量”极易在听觉上混淆。"
    },
    {
      "word": "无粮",
      "explanation": "拼音同为 wúliáng，意为没有粮食，语境和词义截然不同，同音极易引起听觉歧义。"
    },
    {
      "word": "物价",
      "explanation": "拼音为 wùjià，声韵母差异较明显，但在方言区或语速极快时声韵容易与 wúliàng 产生听感混淆。"
    }
  ],
  "primary_collocate": "前途无量",
  "collocation_distractors": [
    {
      "word": "广大",
      "explanation": "“广大”常修饰空间、规模或群众（如“广大人民”），与“无量”语义重叠但语法功能不搭配，不可组合成“广大无量”。"
    },
    {
      "word": "很多",
      "explanation": "“很多”为口语中表示数量多的常用词，属于口语初级词汇，与书面语素“无量”语义风格不合，不能组合为“很多无量”。"
    },
    {
      "word": "无数",
      "explanation": "“无数”表示不可计数，常作定语修饰具体名词（如“无数星星”），与“无量”构成词义冗余，不能直接作其常规固定搭配。"
    }
  ],
  "collocation_wrong_collocate": "面积无量",
  "cloze_distractors": [
    {
      "word": "无限",
      "explanation": "“无限”强调没有边界限制，虽然意思接近，但在成语“前途无量”中不可替换为“前途无限”（习惯上常用“前途无量”）。"
    },
    {
      "word": "无尽",
      "explanation": "“无尽”侧重于没有穷尽、没有终点，多形容思念、苦难等抽象情感或时间，修饰前途属于语域错配。"
    },
    {
      "word": "微薄",
      "explanation": "“微薄”意为微小单薄，与“无量”语义完全相反，放在褒奖语境中语义自相矛盾。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "桌子上放着无量的苹果，大家可以随便吃。",
      "explanation": "“无量”属于书面语且形容极其宏大或不可估量的抽象事物（如功德、前途），不能直接作定语修饰具体、有限的可数生活实物。"
    },
    {
      "sentence": "他今天无量地喝了三杯水。",
      "explanation": "“无量”是形容词，不能直接充当修饰具体动作频次或数量的状语，句法功能错误。"
    },
    {
      "sentence": "这个水杯很无量，能装一升水。",
      "explanation": "“无量”表示不可限量，不能用来描述容量确切、有限的具体容器体积。"
    }
  ],
  "spot_incorrect": {
    "sentence": "这家公司为了谋取暴利生产假药，真是功德无量。",
    "error_description": "“功德无量”是极高的褒义词，用于形容造福众生的善行，不能用于批判作恶造假的企业，属于褒贬误用。",
    "corrected_sentence": "这家公司为了谋取暴利生产假药，真是罪大恶极。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    {
      "fake_form": "无量化",
      "explanation": "错误借用后缀“-化”企图构成动词，现代汉语中不存在“无量化”这一构词。"
    },
    {
      "fake_form": "无量性",
      "explanation": "错误借用抽象名词后缀“-性”构成生造词，汉语中通常用“不可限量”或“无限性”，无“无量性”用法。"
    },
    {
      "fake_form": "无量度",
      "explanation": "错误杂糅“无量”与物理测量名词“量度”，汉语中并无此衍生复合词。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "不可估量",
      "relationship": "synonym"
    },
    {
      "word": "无限",
      "relationship": "synonym"
    },
    {
      "word": "有限",
      "relationship": "antonym"
    },
    {
      "word": "微不足道",
      "relationship": "antonym"
    }
  ],
  "particle_candidates": []
}

{
  "definition_simple": "The degree to which something successfully produces the desired result.",
  "definition_standard": "The capability of producing a desired result or the ability to produce successfully a planned or intended outcome, often evaluated quantitatively or qualitatively.",
  "pos": "noun",
  "semantic_class": "property",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "The doctor checked the effectiveness of the new medicine."
    },
    {
      "tier": "T2",
      "sentence": "Regular practice improves the effectiveness of your study habits."
    },
    {
      "tier": "T2",
      "sentence": "We questioned the effectiveness of the school's new recycling policy."
    },
    {
      "tier": "T3",
      "sentence": "The survey measures the effectiveness of our customer support team."
    },
    {
      "tier": "T3",
      "sentence": "Cost is an important factor, but overall effectiveness should be prioritized."
    },
    {
      "tier": "T4",
      "sentence": "Rigorous clinical trials are conducted to verify the effectiveness and safety of vaccines."
    },
    {
      "tier": "T4",
      "sentence": "The marketing team analyzed user retention metrics to determine advertising effectiveness."
    },
    {
      "tier": "T5",
      "sentence": "Diminishing returns can undermine the operational effectiveness of even well-funded initiatives."
    },
    {
      "tier": "T5",
      "sentence": "Scholars continue to debate the pedagogical effectiveness of standardized testing across diverse socioeconomic backgrounds."
    },
    {
      "tier": "T6",
      "sentence": "Bureaucratic inertia compromised the systemic effectiveness of the newly promulgated regulatory framework."
    }
  ],
  "morphological_forms": [
    {
      "form": "effectivenesses",
      "label": "plural"
    }
  ],
  "morphology_wrong_forms": [
    {
      "base_form": "effectivenesses",
      "wrong_forms": [
        {
          "form": "effectiveness",
          "explanation": "Treated as invariant plural by failing to add the -es inflection when referring to distinct types of efficacy."
        },
        {
          "form": "effectivities",
          "explanation": "Incorrectly applies Latinate -ity pluralization to the Germanic -ness suffix base."
        },
        {
          "form": "effectiveness's",
          "explanation": "Confuses the singular possessive apostrophe-s with the plural inflection."
        }
      ]
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "affectiveness",
      "explanation": "Differs by the initial unstressed vowel /ə/ vs /ɪ/ (affective vs effective), causing frequent spelling and phonological confusion."
    },
    {
      "word": "infectiousness",
      "explanation": "Shares rhythm and the unstressed /-tɪvnəs/ ending, differing in the root morpheme."
    },
    {
      "word": "defectiveness",
      "explanation": "Differs only by the prefix /dɪ-/ versus /ɪ-/, creating an acoustic near-minimal pair with opposite connotations."
    }
  ],
  "primary_collocate": "cost",
  "collocation_distractors": [
    {
      "word": "price",
      "explanation": "'Price-effectiveness' is not an idiomatic compound in English; standard usage strictly prefers 'cost-effectiveness'."
    },
    {
      "word": "expense",
      "explanation": "While semantically synonymous with cost, 'expense-effectiveness' violates conventional lexical pairing."
    },
    {
      "word": "gain",
      "explanation": "'Gain-effectiveness' is not recognized; 'cost-benefit' or 'cost-effectiveness' are the standard functional pairings."
    }
  ],
  "collocation_wrong_collocate": "budget-effectiveness",
  "cloze_distractors": [
    {
      "word": "efficiency",
      "explanation": "Wrong sense: efficiency measures resource usage and waste minimization rather than whether the objective itself was achieved."
    },
    {
      "word": "affectation",
      "explanation": "Trivially unrelated: refers to artificial behavior designed to impress, confused only via superficial morphological similarity to 'affect'."
    },
    {
      "word": "efficacy",
      "explanation": "Wrong register/context: efficacy specifically denotes performance under ideal, controlled conditions rather than real-world operational results."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "The manager praised John for his high effectiveness at completing tasks quickly without any errors.",
      "reason": "Confuses 'effectiveness' with 'efficiency'; doing tasks quickly without wasted time or resources specifically denotes efficiency, whereas effectiveness refers purely to achieving the target goal."
    },
    {
      "sentence": "She effectivenesses the implementation of the new software across all branches.",
      "reason": "Wrong syntactic category; 'effectiveness' is a noun and cannot take verbal inflections or function as the finite predicate."
    },
    {
      "sentence": "The effectiveness between the two proposals was strongly argued during the meeting.",
      "reason": "Wrong argument structure; 'effectiveness' cannot take a reciprocal 'between' complement without an explicit comparative noun phrase like 'difference in effectiveness'."
    }
  ],
  "spot_incorrect": {
    "sentence": "The audit raised serious questions regarding the cost-affectiveness of the municipal transit expansion.",
    "error_description": "Incorrectly substitutes the non-word root 'affectiveness' for the standard spelling 'effectiveness' in the compound noun.",
    "corrected": "The audit raised serious questions regarding the cost-effectiveness of the municipal transit expansion."
  },
  "word_family_forms": [
    {
      "pos": "adjective",
      "form": "effective"
    },
    {
      "pos": "adverb",
      "form": "effectively"
    },
    {
      "pos": "noun",
      "form": "effect"
    },
    {
      "pos": "verb",
      "form": "effect"
    }
  ],
  "word_family_fake_forms": [
    "effectivize",
    "effectful",
    "effectivity"
  ],
  "syn_ant_candidates": [
    {
      "word": "efficacy",
      "relation": "synonym"
    },
    {
      "word": "successfulness",
      "relation": "synonym"
    },
    {
      "word": "ineffectiveness",
      "relation": "antonym"
    },
    {
      "word": "futility",
      "relation": "antonym"
    }
  ],
  "particle_candidates": null
}

{
  "definition_simple": "A surface or piece of land that is higher at one end than the other.",
  "definition_standard": "An inclined line, surface, or piece of ground where one end or side is at a higher elevation than the other, or the degree of such an incline.",
