    {
      "tier": "T1",
      "sentence": "He slipped and fell on the muddy slope."
    },
    {
      "tier": "T2",
      "sentence": "The ski slope was covered in fresh powder this morning."
    },
    {
      "tier": "T2",
      "sentence": "Be careful walking down that steep slope in the rain."
    },
    {
      "tier": "T3",
      "sentence": "The roof has a gentle slope to allow rainwater to run off easily."
    },
    {
      "tier": "T3",
      "sentence": "Houses built on a steep slope require deep foundations to prevent erosion."
    },
    {
      "tier": "T4",
      "sentence": "The hikers rested briefly before tackling the rocky slope of the mountain."
    },
    {
      "tier": "T4",
      "sentence": "Calculating the slope of the line requires dividing the change in vertical distance by horizontal distance."
    },
    {
