      "label": "plural",
      "form": "slopes"
    },
    {
      "label": "singular_possessive",
      "form": "slope's"
    }
  ],
  "morphology_wrong_forms": {
    "slopes": [
      {
        "form": "slopess",
        "explanation": "Erroneously doubles the terminal 's' following a silent 'e' when attempting to form a regular plural."
      },
      {
        "form": "slopi",
        "explanation": "Incorrectly applies a Latinate second-declension '-i' plural suffix to a standard English noun."
      },
      {
        "form": "slopeen",
        "explanation": "Overapplies the archaic Germanic '-en' plural suffix found in irregular words like 'oxen'."
      }
    ],
    "slope's": [
      {
        "form": "slopes's",
        "explanation": "Incorrectly appends both a plural marker and an explicit singular possessive clitic to a singular noun base."
      },
      {
        "form": "slope-is",
        "explanation": "Treats the English genitive clitic as a hyphenated morpheme modeled on obsolete phonetic spellings."
      },
      {
        "form": "slopeth",
        "explanation": "Confuses archaic Early Modern English third-person singular verbal inflection with nominal possession."
      }
    ]
  },
  "l1_audio_confusables": [
    {
      "word": "slop",
      "explanation": "Replaces the diphthong /oʊ/ with the short open vowel /ɒ/ (or /ɑː/), yielding a word meaning liquid spill or waste."
    },
    {
      "word": "slip",
      "explanation": "Substitutes the high front lax vowel /ɪ/ for the mid back diphthong /oʊ/, altering the meaning to losing footing."
    },
    {
      "word": "slow",
      "explanation": "Omits the final voiceless bilabial stop /p/, leaving an open syllable /sloʊ/ denoting a lack of speed."
    }
  ],
  "primary_collocate": "steep slope",
  "collocation_distractors": [
    {
      "word": "sharp slope",
      "explanation": "While 'sharp' pairs with 'turn', 'drop', or 'incline', native English conventionally pairs 'slope' with 'steep' or 'gentle' rather than 'sharp'."
    },
    {
      "word": "tall slope",
      "explanation": "'Tall' applies to vertical objects measured upwards from a base, not to lateral gradients or inclined surfaces."
    },
    {
      "word": "deep slope",
      "explanation": "'Deep' describes depths, cavities, or chasms rather than the angular steepness of an exposed incline."
    }
  ],
  "collocation_wrong_collocate": "high slope",
  "cloze_distractors": [
    {
      "word": "slant",
      "explanation": "Wrong register and semantic nuance; 'slant' primarily denotes an angular tilt or subjective bias rather than a natural landform."
    },
    {
      "word": "grade",
      "explanation": "Wrong sense; 'grade' denotes the mathematical percentage or measurement of an incline rather than the physical hillside terrain."
    },
    {
      "word": "pinnacle",
      "explanation": "Trivially unrelated; 'pinnacle' designates a sharp vertical peak or apex, opposite to an extensive inclined ground surface."
