    "error_description": "The noun 'slope' is incorrectly inflected with an illegitimate '-n' suffix instead of remaining in its base singular form.",
    "corrected_sentence": "The skiers carefully navigated down the icy, steep slope to avoid losing control on the mountain."
  },
  "word_family_forms": [
    "sloping",
    "sloped",
    "aslope"
  ],
  "word_family_fake_forms": [
    "slopement",
    "slopity",
    "slopeless"
