      "word": "gradient",
      "type": "synonym"
    },
    {
      "word": "decline",
      "type": "synonym"
    },
    {
      "word": "flat",
      "type": "antonym"
    }
  ],
  "particle_candidates": null
}

{
  "definition_simple": "在比赛、竞争或斗争中取得胜利。",
